// Two event shapes arrive here, and they are not the same object.
// message.new carries the whole Message: payload.text, payload.chat_id, payload.is_sender,
// payload.sender.display_name. email.new carries payload.email, whose `from` is an ARRAY of
// {email, display_name} and which has no id to read back.
// Everything downstream reads the normalized item, never the raw payload.
const event = $json.payload || {};
const account = $json.account_id || $json.account?.id || null;
const isEmail = Boolean(event.email);
const email = event.email || {};
const from = Array.isArray(email.from) ? email.from[0] || {} : email.from || {};

const out = {
  channel: isEmail ? 'email' : String($json.provider || event.provider || 'messaging').toLowerCase(),
  is_email: isEmail,
  account_id: account,
  // A message the provider did not classify is never treated as inbound.
  is_inbound: isEmail ? true : event.is_sender === false,
  is_event: Boolean(event.is_event),
  sender: (isEmail ? (from.display_name || from.email) : event.sender?.display_name) || 'Unknown sender',
  sender_handle: (isEmail ? from.email : event.sender?.id) || '',
  subject: isEmail ? (email.subject || '(no subject)') : '',
  text: String((isEmail ? (email.body_plain || email.body || '') : event.text) || '').slice(0, 4000),
  chat_id: isEmail ? '' : event.chat_id || '',
  folder_id: isEmail ? event.folder_id || '' : '',
  received_at: event.timestamp || email.date || new Date().toISOString(),
};
return [{ json: out }];

// email.new carries the whole email, body included, and no id to read it back with: there is nothing
// to fetch and nothing to paginate. The model therefore judges an email on the message alone, while a
// chat is judged with its history. Saying so here is cheaper than a call that cannot be made.
return [{ json: { ...$json, context: '(single email, no thread read)', context_unreadable: false, thread_read: false } }];

// The alert exists to interrupt you. It must not interrupt you about something you already handled.
// The conversation is the only state: no database, nothing to clean up if a run fails.
const item = $('Normalize the event').first().json;
const read = item.is_email ? [] : $input.all().map(i => i.json || {});
if (item.is_email) return [{ json: { ...item, skip: false } }];
const failed = read.some(m => m && m.error) || read.length === 0;

// Messages are returned newest first by the chat read and oldest first by the thread read,
// so sort explicitly instead of trusting the order.
const stamped = read
  .filter(m => m && !m.error && (m.timestamp || m.date))
  .map(m => ({ mine: m.is_sender === true || m.from_me === true, at: new Date(m.timestamp || m.date).getTime(), text: String(m.text || m.body_plain || m.snippet || '').slice(0, 300) }))
  .filter(m => Number.isFinite(m.at))
  .sort((a, b) => a.at - b.at);

const last = stamped[stamped.length - 1];
// You answered last: whatever arrived is a follow-up to your own reply, not something waiting on you.
if (last && last.mine) return [{ json: { ...item, skip: true, skip_reason: 'you answered last in this conversation' } }];

// An unreadable conversation is not an empty one. For an alert the safe direction is to speak up:
// the cost of one extra notification to yourself is lower than the cost of missing the message.
const context = stamped.slice(-6).map(m => `${m.mine ? 'you' : item.sender}: ${m.text}`).join('\n');
return [{ json: { ...item, skip: false, context_unreadable: failed, context: failed ? '(conversation could not be read)' : context } }];

values.content:
=You triage everything that reaches one person across their own accounts. Answer with one JSON object and nothing else: {"urgent": true|false, "reason": "max 15 words"}.
Urgent means it needs an answer from them today: a client or candidate waiting, a deadline, a meeting or delivery that moves, money, or someone blocked on them. Not urgent: newsletters, notifications, automated receipts, social pleasantries, anything they can read tomorrow.
Judge the new message in the light of the conversation: a third follow-up on the same question is urgent, a thank-you after your answer is not.

Channel: {{ $json.channel }}
From: {{ $json.sender }}
Subject: {{ $json.subject }}
New message: {{ $json.text }}

Conversation so far:
{{ $json.context }}

