// An urgent email at 03:00 is still not worth a phone buzzing. The alert is held, never dropped.
const s = $('Settings').first().json;
const item = $json;
const zone = s.timezone || 'Europe/Paris';
const start = Number(s.quiet_hours_start), end = Number(s.quiet_hours_end);

const now = new Date();
const hour = Number(new Intl.DateTimeFormat('en-GB', { hour: 'numeric', hour12: false, timeZone: zone }).format(now));
const minute = Number(new Intl.DateTimeFormat('en-GB', { minute: 'numeric', timeZone: zone }).format(now));
// Quiet hours cross midnight when start > end (22 -> 8), and do not when they do not (13 -> 14).
const quiet = start === end ? false : start > end ? hour >= start || hour < end : hour >= start && hour < end;

if (!quiet) return [{ json: { ...item, held: false, hold_seconds: 0 } }];
let hours = end - hour; if (hours < 0) hours += 24;
const hold = Math.max(60, hours * 3600 - minute * 60);
return [{ json: { ...item, held: true, hold_seconds: hold, held_until_hour: end } }];

